        ("jpeds_sbs", "赤ちゃんの機嫌が悪くてぐずるときにイライラしたり腹を立てたりして激しく揺さぶってしまうことで発生すること、「特に、子どもが泣きやまないときによく起こります」という記述、養育者が自制心を失って何とか泣きやませようとして揺さぶるという経緯。「高い、高い」やひざの上でピョンピョンさせる通常のあやし行為ではSBSは起こらない（脳が頭蓋骨の内側に打ちつけられる力が発生しないため）。ただし落下の危険があるため「高い高い」はしない。赤ちゃんは頭が重く頸の筋肉が弱いため頭を支えられず、頭蓋骨の内側に脳が打ち付けられるという仕組み。症状の一覧と、軽症例がカンの強い子・むずがる子と見間違われること。泣きやまないときの具体的な対処手順。"),
