        ("env_uv", "赤ちゃんの皮膚は大人よりデリケートで紫外線の影響に個人差があること、日差しの強い10時〜14時頃を避け朝夕の涼しい時間帯に薄い長袖・帽子・ベビーカーの日よけを使うこと、日陰の利用やつばの広い帽子の効果、通気性が悪いと熱中症の心配があること、母乳栄養やアレルギーで食事制限のある赤ちゃんはビタミンDが不足しがちで冬場は一日15分程度の日差しも効果的とされること。"),
