        ("caa_fall_2022", "0歳では転落の発生場所として「家具等」「抱っこ・おんぶ等」の割合が高いこと。家具等からの転落で入院した97件のうち主たる危害部位は頭部・顔面・首が65件と最も多いこと。大人用ベッドに寝かせるのではなく満2歳になるまではできるだけベビーベッドに寝かせ、寝かしつけのため大人用ベッドを使って添い寝する場合は寝かしつけた後にできるだけベビーベッドに移すこと。床板の高さが変えられるベビーベッドの場合はつかまり立ちをし始めたら床板を低くし、足がかりになる物を中に入れないこと。ベッドの周りに枕・毛布・クッション等を置かないこと、転落時の衝撃緩和やすき間をなくすことが目的であっても子どもの鼻や口を覆ってしまうこと。一時的でも乳幼児をテーブルの上に寝かせるのはやめること。おむつ交換台に乗せる際は事前に準備し、子どもを降ろした後に片付けをすること。ベビーベッドの柵は転落防止のため常に上げて使用すること。入院を必要とする事故のうち転落事故が最も多く約3割を占め、その約6割が頭部を受傷し、高い所に限らず比較的低い所からの転落であっても頭部の骨折や頭蓋内損傷の事故が発生していたこと。"),
