        ("ng", "対象月齢・体重の下限を下回る時期に使わない", "この種の製品は6〜7か月から2歳頃まで、体重12kgまでとするものが一般的です。この下限は、自分で上体を支えられるようになってから使う設計だという意味で、支えられない時期に支えを足すための数字ではありません。"),
