        ("ng", "マークのある製品を探して、早く使い始めない", "ベビーチェアには<strong>PSCマークのような法律上の安全基準がありません</strong>。製品安全協会のSGマークは乳幼児用品全般を対象とした任意の制度で、事例の製品と複数の類似品では、その表示も確認できませんでした。基準に適合しているかを外から確かめる手段がないので、対象月齢の下限を下回るうちは使いません。"),
        ("ok", "落ちて頭を打ったら、意識があっても受診する", "事例の赤ちゃんは、最初の搬送先では眠りがちで、転院した先に着いたときには意識障害がありませんでした。それでも頭蓋骨の骨折と血腫がありました。体に対して頭が大きく重いので、落ちると頭から先に着きます。"),
