        ("ボタン電池", "消化管に触れた電池から電流が流れ、電気分解でアルカリができます。アルカリはタンパク質を溶かすので、消化管の壁が化学やけどを起こします。国民生活センターが生理食塩水に浸した鶏肉に電池を当てた試験では、接触部に沿って損傷ができ、その付近は<strong>pH13を超える強アルカリ</strong>でした。もっとも危険なのは<strong>コイン形リチウム電池</strong>です。電圧が高く放電が速いうえ、大きいものは乳児の食道の狭いところに引っかかり、押し付けられた粘膜がすぐに傷み始めます。<strong>食道に穴があき、その先の大動脈が破れて失血死した例</strong>が報告されています。鼻に入れて鼻中隔が溶けた例もあります。"),
