        ("吸水樹脂ボール", "水で膨らむボールです。<strong>腸の中で膨らんで腸閉塞</strong>を起こします。これも販売規制の対象になりました。"),
        ("たばこ・吸い殻のつかった水", "缶やペットボトルを灰皿の代わりに使うと、<strong>ニコチンが溶け出した液体</strong>ができます。この液体は体に吸収されやすく、特に危険です。飲んだ場合や普段と違う様子があるときは、<strong>何も飲ませず、直ちに受診</strong>します。銘柄名かパッケージを持って行きます。"),
