        ("ng", "ボタン電池と、それを使う製品をテーブルの上に置かない", "未使用のものも使用済みのものも、手の届かない場所にまとめます。製品のどこに電池が使われているかを確かめ、電池のフタが外れやすくなっていないかを点検します。国民生活センターによると、工具なしで1動作で開くスライド式やキャップ式のフタは、落下でも外れます。電池を簡単に取り出せるおもちゃは選びません。<strong>上の子が取り出した電池や、親が電池交換中に置いた電池</strong>での事例が報告されているので、電池交換は小さな子に見せないようにします。"),
