        ("ng", "予防のために、自己判断で早く食べさせない", "学会の提言は<strong>医師の管理のもと</strong>という条件付きです。すでにアレルギーが疑われる子に食べさせるのは、きわめて危険とされています。"),
        ("ok", "初めての食品は、昼のうちに1種類だけ、1さじから試す", "2種類を同時に始めると、どちらで症状が出たのかが分かりません。何を何日に初めて与えたかを書きとめておくと、受診したときに医師へ伝えられます。"),
        ("ok", "子どもに湿疹があるなら、離乳の進め方をかかりつけの小児科で相談する", "皮膚のバリア機能の低下は、食物アレルギーの発症リスクに影響する因子として挙げられています。ただし湿疹があっても、原因食物以外の摂取を遅らせる必要は基本的にありません。乳児期の早い時期に出た湿疹や重い湿疹では、アレルギーを専門にする医師の診療を受けることがすすめられています。"),
