        ("ng", "抱っこしたまま自転車に乗せない", "各都道府県の公安委員会規則では、同乗させるには幼児用座席を使うかおんぶする必要があります。おんぶに替えても勧められないことは、上に書いたとおりです。"),
        ("ng", "この時期は、幼児用座席を使わない", "幼児用座席を使えるのは1歳からが一般的です。製品ごとに下限は違いますが、この時期に使える座席はありません。1歳を過ぎてから、座席の対象年齢を見て選びます。"),
