        ("ng", "小さな磁石とボタン電池を、手の届くところに置かない", "電池から流れた電流で、ふれている粘膜にアルカリ性の液体ができて組織を溶かします。磁石は複数個が腸壁をはさんでくっつきます。どちらも穴があきます。くわしくは4〜6か月の「何でも口に入れる時期の誤飲」に書きました。"),
        ("ng", "缶やペットボトルを灰皿の代わりに使わない", "吸い殻が浸かった水にはニコチンが溶け出し、<strong>液体になったニコチンは体に吸収されやすくなります</strong>。吸い殻はビニール袋に包んで密閉し、たばこと加熱式たばこのスティックは、目に触れない場所にしまいます。10か月児が加熱式たばこを誤飲し、金属のプレートが見つかった事例があります。"),
        ("ng", "食べものの容器に、洗剤などを移し替えない", "詰め替えた本人以外には、中身が伝わりません。ジュースの容器に入れた洗剤を、別の家族が子どもの手元に置いてしまいます。"),
        ("ng", "ふたのないゴミ箱を、床に置かない", "使用済みのおむつ、乾燥剤、吸水シート、電池の包装。捨てたものが、そのまま手の届く範囲にあります。"),
        ("ng", "手指消毒剤を、手の届くところに置かない", "携帯用の容器に詰め替えたアルコールジェルを30ml飲んで点滴を受けた2歳の事例があります。店の入口での噴霧でも事故が起きています。1〜2歳タブ「消毒剤・除菌剤」にまとめました。"),
        ("ng", "来客や祖父母のかばんを、床に置いたままにしない", "家の中は片づけても、持ち込まれたかばんの中は片づいていません。薬やのど飴が入っています。"),
