        "冷蔵庫や引き出しには、<strong>扉の形に合った専用のロック</strong>を選びます。開き戸用は引き出しや冷蔵庫には効きません。",
        "ボタン電池は<strong>個別の仕切りがあるケース</strong>に入れ、使用済みも必ず回収します。使用済みでも、穴があく力は残っています。",
