        ("ok", "歯ぐきでつぶせる硬さまで加熱する", "親指と人差し指で軽くつまんで形が崩れるくらいが目安です。にんじんやさつまいもは、箸がすっと通るまで煮ます。生の野菜スティックは、まだ早いです。"),
