        ("ncac_cutpan", "1歳前後の乳幼児に食事を与える際は、喉を通過するサイズ（1.5cm以下）に小さくちぎって与え、飲み込むまで目を離さないこと。1歳児の口径は3cmほど、喉の大きさは直径1cm以下であること。「10ヶ月頃から」と表示されたカットパンを10か月の男児が食べて窒息し死亡した事例、同じ銘柄のカットパンを11か月の男児が食べて喉に詰まらせ窒息した事例。製造事業者が丸ごと飲み込めないよう商品サイズを縦40mm・横60mm・厚さ20mm程度に変更したこと。"),
        ("ia_babyfood_soy", "10か月が市販のベビーフード（豆と肉入りシチュー80g、対象：9か月〜）を食べた後に気管支異物・化学性肺炎を起こした事例。気管支から排出された大豆片の一つは8mm×3mmであり、この大きさのものが10か月児の気管支に入っていれば気道閉塞に近い状態となり呼吸困難をきたすことは容易に想像できるとされていること。包装容器の外側には「9か月頃から、歯ぐきでつぶせる固さ」と表記があるが、包装容器の注意書きには誤嚥のことは記載されていないこと。ベビーフードの指針にも日本ベビーフード協議会の自主規格にも誤嚥に関する記載はないこと。小児の気管支異物として最も頻度が高いものは豆類であり、豆類は化学性肺炎を起こすこともよく知られていること。本児は食事時に噛まずに飲み込む癖があったこと。"),
        ("caa_bread", "小さな子どもの口の大きさは直径約4cmで喉はそれよりも細く、口に入るものは何でも窒息や誤嚥の原因になりうること。粘着性が高いもの・丸いもの・つるっとしたもの・固くてかみ切りにくいものは特に注意が必要であること。食品に応じて小さくカットし柔らかく調理すること。市販品に表示されている対象月齢はあくまで目安で、与える前に子ども自身の発達を見ること。食事の際は水分をとり喉を湿らせること。"),
        ("cfa_weaning_guide", "手づかみ食べは生後9か月頃から始まり、1歳過ぎの子どもの発育及び発達にとって積極的にさせたい行動であること。9〜11か月頃は歯ぐきでつぶせる固さのものを与えること。食品は子どもが口の中で押しつぶせるように十分な固さになるよう加熱調理をすること。"),
        ("caa_handbook", "食品を口に入れたまま遊んだり、話したり、寝転んだりさせないようにすること。泣いている子どもをあやそうとして食品を食べさせるのはやめること。"),
        ("cfa_guideline", "日常的な点検のチェックリストに「よだれかけを外してから、子どもを寝かせている」「ミルクを飲ませた後は、ゲップをさせてから寝かせる」が挙げられていること。睡眠前及び睡眠中の乳児の窒息リスクの除去として、ヒモまたはヒモ状のもの（例：よだれかけのヒモ）を置かないこと、口の中に異物がないか確認すること、ミルクや食べたもの等の嘔吐物がないか確認すること。"),
