        ("cfa_teeth", "乳歯は上下10本ずつ合計20本あり、生後6〜7か月頃で下の前歯から生え始め、2歳半〜3歳頃に20本が生えそろうこと。歯の生える時期や順序には個人差があること。歯が生える前から口の中を指でやさしくタッチして徐々に準備をし、乳歯が生え始めたら保護者のひざにあお向けに寝かせこどもの歯を観察する（歯を数える）ことから始めること。前歯が生えてきたらガーゼみがきなどから始め、徐々に歯ブラシに慣れさせること。鉛筆を持つ持ち方で力を抜いて歯を見ながら1本ずつやさしくみがき、1本5秒ぐらいで十分であること。歯をきれいにみがくことも大切だが、歯ブラシの刺激に慣れさせ歯みがきを好きになってもらうことが重要であること。嫌がる場合は機嫌の良い時を見計らって行ったり、保護者が楽しそうに歯をみがく様子をみせること。仕上げみがきは寝かせて、こどもが自分でみがくときは必ず座らせ「歯ブラシ喉突き事故」に気をつけること。こどもによる歯みがきは朝食後と寝る前を含む1日2回以上を目安に続けること。生え始めの歯の表面に直接フッ化物を塗布することによってむし歯になりにくい強い歯となり、フッ化物塗布は歯科医院、保健所、市町村保健センターなどで実施されていること。甘いおやつをだらだら食べる習慣はむし歯になりやすいので、おやつは1日2回程度時間と量を決めて食べること。ジュース、イオン飲料や乳酸菌飲料はむし歯になりやすいので注意が必要で、普段の水分補給は水や麦茶などの甘くない飲み物にすること。"),
