        ("cfa_teeth", "仕上げみがきは寝かせて、こどもが自分でみがくときは必ず座らせ、「歯ブラシ喉突き事故」に気をつけること。鉛筆を持つ持ち方で力を抜いて歯を見ながら1本ずつやさしくみがき、1本5秒ぐらいで十分であること。歯をきれいにみがくことも大切だが、歯ブラシの刺激に慣れさせ歯みがきを好きになってもらうことが重要であること。嫌がる場合は機嫌の良い時を見計らって行うこと。"),
