        ("ng", "「言って聞かせた」で対策を終わりにしない", "消費者庁は、ベランダから身を乗り出すと転落する危険があることを教えるよう勧めていますが、それは<strong>補助錠や踏み台の片づけの代わりにはなりません</strong>。"),
