        ("ok", "虫よけは、日焼け止めを塗ったあとに塗る", "順番を逆にすると、虫よけの持続時間が短くなります。<strong>2歳からディートは1日1〜3回まで</strong>に変わります（2歳未満は1日1回まで）。イカリジンには年齢制限がありません。成分と濃度の見方は、4〜6か月タブ「虫よけ剤は、成分で選ぶ」にまとめました。"),
