        ("env_heat_child", "子どもを観察したとき、顔が赤くひどく汗をかいている場合には深部体温がかなり上昇していると推察できるので、涼しい環境下で十分な休息を与えること。気温が高い日に散歩等をする場合、身長の低い幼児は大人よりも危険な状態になり、東京都心で気温が32.3℃だったとき幼児の身長である50cmの高さでは35℃を超え、さらに地面に近い5cmの高さでは36℃以上だったこと。"),
        ("env_heat_firstaid", "熱中症を疑ったときの現場での応急処置として、風通しのよい日陰やクーラーの効いた室内等へ避難させること。軽症・中等症では涼しい場所に移し、衣服を緩め、水分と塩分を補給すること。皮膚を濡らしてうちわや扇風機で扇ぐ、氷やアイスパックなどで冷やすこと。前頚部の両側、腋窩部、鼠径部に広く当てて皮膚直下を流れている血液を冷やすことが有効であること。呼びかけや刺激に対する反応がおかしい、答えがない（意識障害がある）ときは誤って水分が気道に流れ込む可能性があるため、口から水分を飲んでもらうのは禁物であること。最初から症状が強い場合、嘔吐・吐き気などで水分補給ができない、処置をしても症状がよくならない場合には病院に搬送すること。"),
