        ("mlit_yugu", "本指針の対象となる遊具の利用者は、幼児から小学生（おおむね3歳から12歳）を基準とし、身体的能力などが十分でない幼児（おおむね3歳から小学校就学前の者）については保護者が同伴していることを前提とすること。3歳未満の乳幼児にあっては保護者による安全確保が必要であり、遊具を利用する場合には常時保護者等とともに利用することを前提とすること。人的ハザードとして「年齢、能力に適合しない遊具で遊ばせる（幼児が単独で、あるいは保護者に勧められて小学生用遊具で遊ぶなど）」「不適切な服装、持ち物（絡まりやすい紐のついた衣服やマフラー、ヘルメット、ランドセル、サンダル、脱げやすい靴やヒールのある靴などを着用したまま遊ぶ、携帯電話をネックストラップで首から下げたまま遊ぶなど）」を挙げていること。4歳が保護者の付き添いがない状態で登はん系遊具で遊び、高さ2mから落下して右腕を骨折した事例（当該遊具には利用対象年齢6〜12歳の看板があり、3〜6歳の幼児には大人が必ず付き添うよう明記されていた）。6歳がラダーの上から落下した際に背負っていたランドセルが引っかかり首つり状態になった事例。"),
