        ("yokohama_playground", "フードがついていない服を着ること、マフラーやヘルメットを取ること（遊具に引っかかる）、運動靴を履きサンダルを避けること、靴のひもを強く結ぶこと、かばんやランドセルを置くこと。壊れている遊具・雨でぬれている遊具・太陽で熱くなっている遊具は使わないこと。遊具には対象年齢のシールが貼ってあり、シールの年齢より小さい子どもが遊ぶときは大人が必ず近くにいること。小さい子どもは頭が重いためバランスを崩して転ぶことがあり、力が弱いためひとりで遊具につかまることができないこと。"),
