        ("28以上31未満 ── 厳重警戒", "<strong>激しい運動は中止</strong>。持久走など体温が上がりやすい運動は避け、10〜20分おきに休憩をとって水分と塩分を補給します。体力の低い子、肥満の子、暑さに慣れていない子は軽減または中止します。夏の多くの日が、この帯に入ります。"),
        ("25以上28未満 ── 警戒", "積極的に休憩をとります。激しい運動では<strong>30分おきくらい</strong>に休憩を入れます。"),
        ("21以上25未満 ── 注意", "<strong>この範囲でも死亡事故は起きます</strong>。兆候に注意し、運動の合間に水分と塩分をとらせます。"),
        ("21未満 ── ほぼ安全", "危険は小さいものの、適宜水分と塩分の補給は必要です。"),
