        ("ng", "「汗が出なくなった」を、落ち着いたしるしと読まない", "環境省は、最重症の熱射病の主な症状を<strong>高体温に加えて、意識障害と発汗停止</strong>としています。汗が止まるのは、悪化のしるしです。"),
