        ("kokusen_game", "契約当事者が小学生・中学生・高校生のオンラインゲームに関する2022年度の相談件数は4,024件で、契約購入金額の平均は約33万円と高額であること。特にスマートフォンやタブレット端末での小学生・中学生の無断課金に関する相談が目立つこと。相談事例として、母親のアカウントにログインした状態のスマホを小学生の娘に貸したところ娘がアカウントのパスワードを変更して登録済みのクレジットカードで課金した事例、課金に母親の指紋認証が必要な設定にしていたが母親のアカウントにログインした状態であったため小学生の息子が自分の指紋を追加登録して約5万円課金した事例、中学生の息子が5か月の間にキャリア決済で約5万円課金し保護者は上限額を引き下げられることを知らなかった事例、中学生の息子が1年前から総額約55万円を課金し数年前に母親がゲーム課金以外の目的で入力したクレジットカード番号が使われた事例。保護者へのアドバイスとして、保護者のスマホで遊ばせる場合は保護者のアカウント（AppleやGoogle）を必ずログオフすること、子ども専用のアカウントを作成しペアレンタルコントロール機能で課金を承認制に設定すること、アカウント決済とキャリア決済のそれぞれに決済時の承認を設定しパスワードは子どもが類推できない文字列にすること、子どものスマホに入力したクレジットカード情報は忘れずに削除すること、キャリア決済は必要に応じ上限額を低くすること、日頃から決済完了メールや明細を確認すること、子どもが遊ぶゲームの課金の仕組みを一緒に確認しルールを決めること。民法では未成年者が保護者の同意なく契約した場合は取り消すことができるが、子どもが保護者のアカウントでログインしたスマホで課金した場合はアカウントの所有者である保護者が決済を行ったとみなされる場合もあること。消費者ホットライン「188」番。"),
