        ("mext_swim_dive", "飛び込みによるスタート時に、深く入水し水底に頭部を打ちつける重大事故が起きていること。重大事故の例として、中学校の水泳部の活動で飛び込み台から飛び込み練習を行い水底で前頭部を打ち、しびれがあり下半身の感覚がない・声を出すのも厳しい等の訴えがあった事例、飛び込んで着水するまでの意識はあったがその後気づいたら水の中で体を動かすことができないことに気づいた事例、スタート台からの飛び込み練習の際にプールの底で頭部を強打し意識はあるが感覚を失った状態で浮いてきた事例の3件（いずれも中学校）。高等学校の入学年次の次年以降及び水泳部の活動で飛び込みによるスタートを行う際は、飛び込みによるスタートが安全に行えるプールであること、安全に指導できる教師又は外部指導者が立ち会い直接指導すること、生徒の体力や技能の程度を踏まえた段階的な指導を行うことといった適切な安全対策を確実に講じることが必要であること。飛び込み事故の防止には正しいスタート技術の習得とその教育が重要であり、日本水泳連盟の「スタートの段階指導」および「プール水深とスタートの高さに関するガイドライン」も参考にすること。"),
