        ("npa_mlit_carleaflet", "シートベルトは成人用に作られているため、子供がチャイルドシートを使用せずシートベルトを装着した場合、衝突時に体を適切に保護できず首等に重大な傷害が発生するおそれがあること。シートベルトが首や腹部を圧迫すること。抱っこも大変危険で、衝突時に子供の体重を支えきれないこと。チャイルドシートは子どもの体格にあったものを選ぶこと。お子様はできるだけ後部座席に乗せるようにすること。助手席では、膨張するエアバッグにより子供に被害が及ぶ場合があること。エアバッグは衝突時に乗員の被害を軽減する安全装置だが、成人の体型を前提に設計されているため、体が小さい子供には適切に機能しないことや、被害を大きくすることがあること。助手席にチャイルドシートを取り付ける場合は、助手席のシートを一番後ろに下げて前向きに取り付けること。助手席に後ろ向きチャイルドシートを取り付けることは危険であること。国の安全基準への適合が確認されたチャイルドシートにはEマークなどの表示があること。"),
